422	class WorksGridFeedRuntime {
423	  private readonly _state: WorksPageState;
424	  private readonly _elements: WorksPageElements;
425	  private _feedState: WorksGridFeedState = {
426	    nextOffset: null,
427	    hasMore: false,
428	  };
429	  private _abortController: AbortController | null = null;
430	  private _loading = false;
431	  private _thresholdArmed = true;
432	  private _bound = false;
433	  private readonly _videoHoverCleanups: Array<() => void> = [];
434	  private _category: string | null;
435	  private _sentinel: HTMLDivElement | null = null;
436	  private _sentinelObserver: IntersectionObserver | null = null;
437	  private _filterModal: HTMLDivElement | null = null;
438	  private readonly _filterModalCleanups: Array<() => void> = [];
439	
440	  constructor(state: WorksPageState, elements: WorksPageElements) {
441	    this._state = state;
442	    this._elements = elements;
443	    this._category = state.category;
444	  }
445	
446	  async init(): Promise<void> {
447	    const list = this._elements.gridList;
448	    if (!list) return;
449	    this._clearList();
450	    this._feedState = {
451	      nextOffset: null,
452	      hasMore: false,
453	    };
454	    this._syncRootState();
455	    this._abortController?.abort();
456	    this._abortController = new AbortController();
457	    const grid = this._elements.grid;
458	    if (grid) grid.dataset.loading = "true";
459	    try {
460	      const response = await this._fetchItems(this._resolveInitialOffset());
461	      this._appendItems(response.items);
462	      this._feedState = {
463	        nextOffset: response.nextOffset,
464	        hasMore: response.hasMore,
465	      };
466	      this._syncRootState();
467	      this._syncPaginationVisibility();
468	      this._attachSentinel();
469	    } catch (error) {
470	      if (error instanceof DOMException && error.name === "AbortError") return;
471	      throw error;
472	    } finally {
473	      this._abortController = null;
474	      if (grid) delete grid.dataset.loading;
475	    }
476	  }
477	
478	  bind(): void {
479	    if (this._bound) return;
480	    window.addEventListener("scroll", this._handleScroll, { passive: true });
481	    this._bound = true;
482	    this._bindFilterModal();
483	  }
484	
485	  dispose(): void {
486	    if (this._bound) {
487	      window.removeEventListener("scroll", this._handleScroll);
488	      this._bound = false;
489	    }
490	    this._abortController?.abort();
491	    this._abortController = null;
492	    this._loading = false;
493	    this._thresholdArmed = true;
494	    this._runVideoHoverCleanups();
495	    this._detachSentinel();
496	    this._removeFilterModal();
497	  }
498	
499	  async changeCategory(category: string | null): Promise<void> {
500	    this._category = category;
501	    this._elements.root?.setAttribute("data-category", category ?? "");
502	    await this.init();
503	    this._syncFilterModalSelection(category);
504	  }
505	
506	  private readonly _handleScroll = (): void => {
507	    if (!this._feedState.hasMore) return;
508	    if (this._loading) return;
509	    const list = this._elements.gridList;
510	    if (!list) return;
511	    const thresholdReached = this._isThresholdReached(list);
512	    if (!thresholdReached) {
513	      this._thresholdArmed = true;
514	      return;
515	    }
516	    if (!this._thresholdArmed) return;
517	    this._thresholdArmed = false;
518	    void this._loadMore();
519	  };
520	
521	  private _isThresholdReached(list: HTMLElement): boolean {
522	    const rect = list.getBoundingClientRect();
523	    return (
524	      rect.bottom - ResponsiveRuntime.getDefault().getSnapshot().viewportHeight <=
525	        WORK_GRID_INFINITE_CONFIG.thresholdPx
526	    );
527	  }
528	
529	  private _attachSentinel(): void {
530	    this._detachSentinel();
531	    if (!this._feedState.hasMore) return;
532	    const list = this._elements.gridList;
533	    if (!list) return;
534	    const sentinel = document.createElement("div");
535	    sentinel.style.height = "1px";
536	    sentinel.setAttribute("aria-hidden", "true");
537	    list.after(sentinel);
538	    this._sentinel = sentinel;
