802	  private _attachVideoHover(
803	    li: HTMLLIElement,
804	    videoUrl: string,
805	    figure: HTMLElement,
806	  ): void {
807	    const video = document.createElement("video");
808	    video.muted = true;
809	    video.loop = true;
810	    video.playsInline = true;
811	    video.preload = "none";
812	    figure.append(video);
813	
814	    let isHovered = false;
815	    let pendingPlay: Promise<void> | null = null;
816	
817	    const show = (): void => {
818	      if (!isHovered) return;
819	      video.style.opacity = "";
820	      figure.classList.add("is-video-active");
821	    };
822	
823	    const hideVideoNow = (): void => {
824	      video.style.opacity = "0";
825	      figure.classList.remove("is-video-active");
826	    };
827	
828	    const safePause = (): void => {
829	      video.pause();
830	      video.currentTime = 0;
831	    };
832	
833	    const onEnter = (): void => {
834	      isHovered = true;
835	      video.style.opacity = "";
836	      if (!video.src) {
837	        video.src = videoUrl;
838	        video.load();
839	      }
840	      pendingPlay = video.play().catch(() => undefined);
841	      if (video.readyState >= 3) {
842	        show();
843	      } else {
844	        video.addEventListener("canplay", show, { once: true });
845	      }
846	    };
847	
848	    const onLeave = (): void => {
849	      isHovered = false;
850	      video.removeEventListener("canplay", show);
851	      hideVideoNow();
852	      const p = pendingPlay;
853	      pendingPlay = null;
854	      if (p !== null) {
855	        void p.then(() => { if (!isHovered) safePause(); });
856	      } else {
857	        safePause();
858	      }
859	    };
860	
861	    li.addEventListener("pointerenter", onEnter);
862	    li.addEventListener("pointerleave", onLeave);
863	
864	    this._videoHoverCleanups.push(() => {
865	      isHovered = false;
866	      video.removeEventListener("canplay", show);
867	      figure.classList.remove("is-video-active");
868	      const p = pendingPlay;
869	      pendingPlay = null;
870	      if (p !== null) {
871	        void p.then(safePause);
872	      } else {
873	        safePause();
874	      }
875	      li.removeEventListener("pointerenter", onEnter);
876	      li.removeEventListener("pointerleave", onLeave);
877	    });
878	  }
