190	  readHalfView(camera: THREE.Camera): WorksHalfViewBounds {
191	    if (camera instanceof THREE.OrthographicCamera) {
192	      return {
193	        hW: (camera.right - camera.left) * 0.5,
194	        hH: (camera.top - camera.bottom) * 0.5,
195	      };
196	    }
197	    const perspectiveCamera = camera as THREE.PerspectiveCamera;
198	    const fov = (perspectiveCamera.fov * Math.PI) / 180;
199	    const halfHeight = Math.tan(fov / 2) * perspectiveCamera.position.z;
200	    return {
201	      hW: halfHeight * perspectiveCamera.aspect,
202	      hH: halfHeight,
203	    };
204	  }
