424	class WorksThumbnailRuntime {
425	  async warm(
426	    meshes: ReadonlyArray<THREE.Mesh>,
427	    placeholderImage: string,
428	    cardSize: WorkCardSize,
429	    log: (step: string, payload?: Record<string, unknown>) => void,
430	    onImageLoaded?: (mesh: THREE.Mesh, image: HTMLImageElement) => void,
431	  ): Promise<void> {
432	    let fallback: HTMLImageElement | null = null;
433	    const ensureFallback = async (): Promise<HTMLImageElement> => {
434	      if (!fallback) {
435	        fallback = await WorkCard.loadPlaceholderImage(placeholderImage);
436	      }
437	      return fallback;
438	    };
439	
440	    let index = 0;
441	    const batchSize = 4;
442	    const runBatch = async (): Promise<void> => {
443	      const end = Math.min(index + batchSize, meshes.length);
444	      const slice = meshes.slice(index, end);
445	      await Promise.all(
446	        slice.map(async (mesh) => {
447	          if (!mesh) return;
448	          const userData = mesh.userData as WorkCardUserData;
449	          const material = mesh.material as THREE.MeshBasicMaterial;
450	          const map = material.map;
451	          if (!map || !(map instanceof THREE.CanvasTexture)) return;
452	          const thumb = userData.proj.thumbnailImage?.trim() ?? "";
453	          let img: HTMLImageElement;
454	          if (thumb) {
455	            try {
456	              img = await WorkCard.loadImage(thumb);
457	            } catch {
458	              img = await ensureFallback();
459	            }
460	          } else {
461	            img = await ensureFallback();
462	          }
463	          WorkCard.updateTextureImage(
464	            map,
465	            userData.proj,
466	            cardSize,
467	            img,
468	            SCATTER_CARD_RENDER_OPTIONS,
469	          );
470	          onImageLoaded?.(mesh, img);
471	        }),
472	      );
473	      index = end;
474	      log("warmThumbnails.batch", { updatedUntil: index, total: meshes.length });
475	      if (index < meshes.length) {
476	        FrameScheduler.request(() => {
477	          void runBatch();
478	        });
479	      }
480	    };
481	    void runBatch();
482	  }
483	}
